(function () {
  var NAVY = '#0B1A3D', GRAY = '#8A94A6';
  function esc(s){ return String(s).replace(/[&<>"]/g, function(c){ return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]; }); }
  /* Codes are written many ways ("IS C2 H001", "ISC2-H001") — compare letters+digits only. */
  function norm(s){ return String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, ''); }
  function prep(p){
    if (!p.__nn){
      p.__nn = norm(p.n);
      p.__nc = norm(p.c);
      /* the name with words KEPT apart, surrounded by spaces, so a query can
         be required to start on a word. __nn (separators stripped) stays for
         code-shaped queries only. */
      p.__nsp = ' ' + String(p.n).toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim() + ' ';
      p.__codes = (p.k ? p.k.split('|') : []).map(function(c){ return { raw: c, nn: norm(c) }; });
      /* keywords are matched but never shown — see the `w` note in the index */
      p.__nw = ' ' + String(p.w || '').toLowerCase().split(/[^a-z0-9]+/).join(' ') + ' ';
      /* everything this entry can be found by, as space-separated words:
         name + category + keywords + codes. Used by the word-level tier. */
      p.__hay = (' ' + [p.n, p.c, p.w || '', (p.k || '').split('|').join(' ')].join(' ')
        .toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim() + ' ');
    }
    return p;
  }
  /* Three tiers, best first:
       0-99    the query appears in the NAME, starting on a word boundary
       100-199 it appears in a product CODE ("ISC2-H001" -> "IS C2 H001")
       200+    every WORD of the query appears somewhere in the entry — name,
               category, keywords or code — in any order. This is the tier that
               makes "hood", "espresso", "hepa" and "hob built in" work.
     The first two are order-sensitive on purpose: they are what make an exact
     product name or a typed code rank above a loose word hit. */
  function match(p, nq, qsp, words){
    prep(p);
    /* tier 1: the query appears in the NAME, starting on a word boundary.
       (It used to run on the separator-stripped name, which is how "tea"
       matched "steam". Codes still get separator-blind matching in tier 2.) */
    var pos = qsp ? p.__nsp.indexOf(qsp) : -1;
    if (pos > -1) return { p: p, code: null, score: pos };
    var best = null;
    for (var i = 0; i < p.__codes.length; i++){
      var at = p.__codes[i].nn.indexOf(nq);
      if (at > -1 && (!best || at < best.at)) best = { at: at, raw: p.__codes[i].raw };
    }
    if (best) return { p: p, code: best.raw, score: 100 + best.at };

    if (words.length){
      var first = -1;
      for (var w = 0; w < words.length; w++){
        /* leading space = match at a word START. Without it "tea" matched
           "steam" and ranked a vacuum above the kettles. Plurals and partial
           words still work: " chimney" hits " chimneys". */
        var hit = p.__hay.indexOf(" " + words[w]);
        if (hit < 0) return null;                 // every word must be present
        if (first < 0 || hit < first) first = hit;
      }
      /* a hit inside the name beats one that only matched a keyword */
      var inName = p.__nsp.indexOf(' ' + words[0]) > -1 ? 0 : 40;
      return { p: p, code: null, score: 200 + inName + Math.min(first, 39) };
    }
    return null;
  }
  function init(box){
    var input = box.querySelector('input');
    if (!input || box.__searchReady) return;
    box.__searchReady = true;
    var panel = document.createElement('div');
    panel.setAttribute('role','listbox');
    panel.style.cssText = 'position:fixed;display:none;z-index:99999;width:380px;max-width:calc(100vw - 24px);max-height:70vh;overflow:auto;background:#f4f2ee;border:1px solid rgba(90,88,82,0.28);border-radius:14px;box-shadow:0 24px 60px rgba(30,28,24,0.28);padding:6px;font-family:inherit;';
    document.body.appendChild(panel);
    var hits = [];
    function place(){
      var r = box.getBoundingClientRect();
      var w = panel.offsetWidth || 380;
      panel.style.top = (r.bottom + 10) + 'px';
      panel.style.left = Math.max(12, Math.min(r.left, window.innerWidth - w - 12)) + 'px';
    }
    function itemHTML(h){
      var p = h.p;
      var eyebrow = h.code ? p.c + ' · ' + h.code : p.c;
      var thumb = p.i
        ? '<span style="flex:0 0 42px;width:42px;height:42px;border-radius:8px;overflow:hidden;background:#fff;border:1px solid rgba(11,26,61,0.08);display:flex;align-items:center;justify-content:center;">'
          + '<img src="'+p.i+'" alt="" loading="lazy" style="max-width:100%;max-height:100%;object-fit:contain;mix-blend-mode:multiply;"></span>'
        : '<span style="flex:0 0 42px;width:42px;height:42px;border-radius:8px;background:rgba(11,26,61,0.05);display:flex;align-items:center;justify-content:center;">'
          + '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="' + NAVY + '" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" opacity=".55" aria-hidden="true">'
          + '<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/></svg></span>';
      return '<a href="'+p.u+'" style="display:flex;align-items:center;gap:12px;padding:8px 10px;border-radius:9px;text-decoration:none;">'
        + thumb
        + '<span style="flex:1 1 auto;min-width:0;">'
        + '<span style="display:block;font-size:13.5px;font-weight:600;color:'+NAVY+';line-height:1.3;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">'+esc(p.n)+'</span>'
        + '<span style="display:block;font-size:10.5px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:'+GRAY+';margin-top:2px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">'+esc(eyebrow)+'</span>'
        + '</span></a>';
    }
    function render(){
      var nq = norm(input.value);
      if (!nq){ panel.style.display='none'; panel.innerHTML=''; hits=[]; return; }
      /* words of 2+ chars; 1-char fragments would match almost everything */
      var words = input.value.toLowerCase().split(/[^a-z0-9]+/)
                       .filter(function(w){ return w.length > 1; });
      var qsp = input.value.toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
      qsp = qsp ? ' ' + qsp : '';
      hits = SEARCH_INDEX.map(function(p){ return match(p, nq, qsp, words); })
        .filter(Boolean)
        .sort(function(a,b){ return a.score - b.score; })
        .slice(0,8);
      panel.innerHTML = hits.length ? hits.map(itemHTML).join('')
        : '<div style="padding:14px 12px;font-size:13px;color:'+GRAY+';">No results found</div>';
      panel.style.display='block';
      place();
    }
    input.addEventListener('input', render);
    input.addEventListener('keyup', render);
    input.addEventListener('focus', function(){ if (input.value.trim()) render(); });
    input.addEventListener('keydown', function(e){
      if (e.key === 'Enter'){ e.preventDefault(); if (hits.length) window.location.href = hits[0].p.u; }
      else if (e.key === 'Escape'){ panel.style.display='none'; input.blur(); }
    });
    window.addEventListener('resize', function(){ if (panel.style.display==='block') place(); });
    window.addEventListener('scroll', function(){ if (panel.style.display==='block') place(); }, true);
    document.addEventListener('click', function(e){ if (!box.contains(e.target) && !panel.contains(e.target)) panel.style.display='none'; });
  }
  function initToggle(nav){
    /* querySelectorAll, not querySelector: since 2026-08-11 there are TWO
       magnifiers in the markup — the inline one after "Home" (desktop) and the
       one beside the burger (mobile). Only one is ever visible, but binding
       just the first left the other dead depending on source order. */
    var toggles = nav.querySelectorAll('.isler-nav__search-toggle');
    var box = nav.querySelector('.isler-nav__search');
    if (!toggles.length || !box) return;
    var input = box.querySelector('input');
    function setExpanded(open){
      for (var i = 0; i < toggles.length; i++) {
        toggles[i].setAttribute('aria-expanded', open ? 'true' : 'false');
      }
    }
    for (var i = 0; i < toggles.length; i++) {
      (function (toggle) {
        if (toggle.__ready) return;
        toggle.__ready = true;
        toggle.addEventListener('click', function (e) {
          e.preventDefault();
          nav.classList.remove('is-open');
          var open = nav.classList.toggle('is-search-open');
          setExpanded(open);
          if (open && input) setTimeout(function () { input.focus(); }, 60);
        });
      })(toggles[i]);
    }
    if (nav.__outsideReady) return;
    nav.__outsideReady = true;
    document.addEventListener('click', function (e) {
      if (!nav.contains(e.target)) { nav.classList.remove('is-search-open'); setExpanded(false); }
    });
  }
  function boot(){
    document.querySelectorAll('.isler-nav__search').forEach(init);
    document.querySelectorAll('.isler-nav').forEach(initToggle);
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot); else boot();
  window.addEventListener('load', boot);
})();
